// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract BasicMath {
    function adder(uint _a, uint _b) external pure returns (uint sum, bool error) {
        unchecked {
            uint _c = _a + _b;
            if (_c < _a) {
                return (0, true);
            }
            return (_c, false);
        }
    }

    function subtractor(uint _a, uint _b) external pure returns (uint difference, bool error) {
        if (_b > _a) {
            return (0, true);
        }
        unchecked {
            return (_a - _b, false);
        }
    }
}

contracts/BaseLearn/ControlStructures.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ControlStructures {
    error AfterHours(uint _time);

    function fizzBuzz(uint _number) external pure returns (string memory) {
        if (_number % 3 == 0) {
            if (_number % 5 == 0) {
               return "FizzBuzz";
            }
            return "Fizz";
        } else if (_number % 5 == 0) {
            return "Buzz";
        }
        return "Splat";
    }

    function doNotDisturb(uint _time) external pure returns (string memory) {
        assert(_time < 2400);
        if (_time > 2200 || _time < 800) {
            revert AfterHours(_time);
        }
        if (_time > 800 && _time < 1199) {
            return "Morning!";
        }
        if (_time > 1200 && _time < 1259) {
            revert("At lunch!");
        }
        if (_time > 1300 && _time < 1799) {
            return "Afternoon!";
        }
        return "Evening!";
    }
}

